try:
    with open(schema_path) as f:
        schema_doc = yaml.safe_load(f) if yaml else json.load(f)
except Exception:
    schema_doc = {
        "schema": {
            "required": ["schema_version", "generated_at", "generated_by", "verdict", "gates"]
        }
    }

if "schema" not in schema_doc:
    schema_doc = {
        "schema": {
            "required": ["schema_version", "generated_at", "generated_by", "verdict", "gates"]
        }
    }

schema = schema_doc["schema"]
